package com.dinkolami.dinnote;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.*;import android.content.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,items; EditText editor,titleEditor; String selected=null; boolean maktabah=false; android.content.SharedPreferences prefs;
 int green=Color.rgb(47,53,61), gold=Color.rgb(108,115,125);
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("notes",0);home();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(green);t.setPadding(24,20,24,20);return t;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(248,249,251));setContentView(root);TextView h=text(title,24);h.setTextColor(0xff30343b);h.setPadding(28,28,28,28);h.setBackgroundColor(0xffeceef1);root.addView(h);}
 void home(){editor=null;titleEditor=null;selected=null;base("DinNote     •     Catatan & Ilmu");TextView welcome=text("Assalamualaikum\nRuang catatan peribadi anda",15);welcome.setTextColor(0xff646b75);root.addView(welcome);LinearLayout tabs=new LinearLayout(this);Button notes=new Button(this);notes.setText("✎ Nota");Button books=new Button(this);books.setText("▤ Maktabah");tabs.addView(notes,new LinearLayout.LayoutParams(0,-2,1));tabs.addView(books,new LinearLayout.LayoutParams(0,-2,1));root.addView(tabs);notes.setOnClickListener(v->{maktabah=false;home();});books.setOnClickListener(v->{maktabah=true;home();});notes.setTextColor(maktabah?green:Color.WHITE);books.setTextColor(maktabah?Color.WHITE:green);notes.setBackgroundTintList(android.content.res.ColorStateList.valueOf(maktabah?0xffeceef1:green));books.setBackgroundTintList(android.content.res.ColorStateList.valueOf(maktabah?green:0xffeceef1));Button add=new Button(this);add.setText(maktabah?"+ Kitab baharu":"+ Nota baharu");add.setTextColor(Color.WHITE);add.setBackgroundTintList(android.content.res.ColorStateList.valueOf(green));add.setAllCaps(false);root.addView(add);add.setOnClickListener(v->edit(null));EditText search=new EditText(this);search.setSingleLine(true);search.setHint(maktabah?"Cari kitab":"Cari nota");search.setPadding(28,18,28,18);search.setBackgroundTintList(android.content.res.ColorStateList.valueOf(gold));root.addView(search);TextView section=text(maktabah?"KOLEKSI KITAB":"SENARAI NOTA",13);section.setTextColor(gold);root.addView(section);ScrollView sc=new ScrollView(this);items=new LinearLayout(this);items.setOrientation(1);sc.addView(items);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){list(s.toString());}public void afterTextChanged(Editable e){}});list("");}
 void list(String filter){items.removeAllViews();ArrayList<String> keys=new ArrayList<>();for(String k:prefs.getAll().keySet())if(k.startsWith(maktabah?"m_":"n_"))keys.add(k);Collections.sort(keys,Collections.reverseOrder());if(keys.isEmpty()){TextView empty=text(maktabah?"▤  Belum ada kitab\nTekan + Kitab baharu untuk bermula":"✎  Belum ada nota\nTekan + Nota baharu untuk mula mencatat",17);empty.setGravity(Gravity.CENTER);empty.setTextColor(0xff727985);empty.setPadding(28,80,28,80);items.addView(empty);}for(String k:keys){String v=prefs.getString(k,"");String heading=prefs.getString("title_"+k,"");String shown=(heading.isEmpty()?(v.isEmpty()?"Tanpa tajuk":v.split("\n",2)[0]):heading);if(!(heading+" "+v).toLowerCase().contains(filter.toLowerCase()))continue;String preview=v.replace("\n"," ");TextView t=text("✦  "+shown+"\n"+(preview.length()>100?preview.substring(0,100)+"…":preview),17);t.setBackgroundColor(Color.WHITE);t.setPadding(30,28,30,28);items.addView(t);View line=new View(this);line.setBackgroundColor(0xffe5e9e5);items.addView(line,new LinearLayout.LayoutParams(-1,1));t.setOnClickListener(w->edit(k));}}
 void edit(String key){editor=null;selected=key;base("DinNote  /  Editor");LinearLayout bar=new LinearLayout(this);Button back=new Button(this);back.setText("← Kembali");back.setAllCaps(false);bar.addView(back);back.setOnClickListener(v->{save();home();});Button del=new Button(this);del.setText("Padam");del.setAllCaps(false);bar.addView(del);del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Padam nota ini?").setPositiveButton("Padam",(d,w)->{if(selected!=null)prefs.edit().remove(selected).remove("title_"+selected).apply();selected=null;home();}).setNegativeButton("Batal",null).show());root.addView(bar);TextView status=text("Disimpan secara automatik",12);status.setTextColor(0xff68717d);root.addView(status);TextView hint=text("TAJUK & KANDUNGAN",12);hint.setTextColor(gold);root.addView(hint);titleEditor=new EditText(this);titleEditor.setSingleLine(true);titleEditor.setTextSize(20);titleEditor.setTextColor(green);titleEditor.setHint(maktabah?"Tajuk kitab":"Tajuk nota");titleEditor.setPadding(28,18,28,18);titleEditor.setBackgroundColor(0xfff2f3f5);root.addView(titleEditor);if(key!=null)titleEditor.setText(prefs.getString("title_"+key,""));titleEditor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){save();}public void afterTextChanged(Editable e){}});editor=new EditText(this);editor.setGravity(Gravity.TOP);editor.setTextSize(16);editor.setMinLines(8);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setTextColor(0xff30343b);editor.setPadding(28,24,28,24);editor.setLineSpacing(5,1.08f);editor.setHint(maktabah?"Tulis kandungan kitab di sini…":"Tulis nota di sini…");editor.setBackgroundColor(Color.WHITE);root.addView(editor,new LinearLayout.LayoutParams(-1,0,1));if(key!=null)editor.setText(prefs.getString(key,""));editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){save();}public void afterTextChanged(Editable e){}});}
 void save(){if(editor==null||selected==null&&(editor.getText().toString().trim().isEmpty()&&(titleEditor==null||titleEditor.getText().toString().trim().isEmpty())))return;String value=editor.getText().toString();if(selected==null)selected=(maktabah?"m_":"n_")+System.currentTimeMillis();prefs.edit().putString(selected,value).putString("title_"+selected,titleEditor==null?"":titleEditor.getText().toString()).apply();}
 public void onBackPressed(){if(editor!=null){save();editor=null;home();}else super.onBackPressed();}
}
